// The publisher's details that French law (LCEN art. 6-III) puts on the legal
// notice. They come from the environment so the home address and phone number
// stay out of the public source: .env.local in development, Docker build
// arguments in production (see .env.example and the Dockerfile).
//
// next.config.ts inlines them at build time, so prerendered pages, pages
// regenerated by the running server and client components all get them, and
// it fails a production build when one is missing. In development, a missing
// value shows as a visible placeholder.

const publisherVariables = {
  address: "VITRINE_PUBLISHER_ADDRESS",
  phone: "VITRINE_PUBLISHER_PHONE",
  siren: "VITRINE_PUBLISHER_SIREN",
} as const;

type PublisherVariable =
  (typeof publisherVariables)[keyof typeof publisherVariables];

// Each name is spelled out: Next.js only inlines literal process.env.NAME.
const address = configured(process.env.VITRINE_PUBLISHER_ADDRESS);
const phone = configured(process.env.VITRINE_PUBLISHER_PHONE);
const sirenDigits = configured(process.env.VITRINE_PUBLISHER_SIREN)?.replace(
  /\s+/g,
  "",
);

export const publisher = {
  // One line, as printed: "street, postcode city, country".
  address: address ?? placeholder(publisherVariables.address),
  // As printed, for example "+33 6 00 00 00 00".
  phone: phone ?? placeholder(publisherVariables.phone),
  // "123 456 789", as printed in the legal documents.
  siren: sirenDigits
    ? sirenDigits.replace(/^(\d{3})(\d{3})(\d{3})$/, "$1 $2 $3")
    : placeholder(publisherVariables.siren),
  // "123456789", for structured data.
  sirenDigits: sirenDigits ?? placeholder(publisherVariables.siren),
};

// The values next.config.ts inlines. A production build passes required: it
// then fails, naming every variable to set, rather than ship incomplete legal
// pages.
export function publisherBuildEnvironment({
  required,
}: {
  required: boolean;
}): Partial<Record<PublisherVariable, string>> {
  const environment: Partial<Record<PublisherVariable, string>> = {};
  const problems: string[] = [];
  for (const name of Object.values(publisherVariables)) {
    const value = configured(process.env[name]);
    if (!value) problems.push(`${name} is not set`);
    else if (name === publisherVariables.siren && !isSiren(value)) {
      problems.push(`${name} must be 9 digits`);
    } else environment[name] = value;
  }
  if (required && problems.length > 0) {
    throw new Error(
      `The legal pages need the publisher's details: ${problems.join(", ")}. ` +
        "Set them in packages/vitrine/.env.local, or as Docker build " +
        "arguments in production (see packages/vitrine/.env.example).",
    );
  }
  return environment;
}

function configured(value: string | undefined) {
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
}

function isSiren(value: string) {
  return /^\d{9}$/.test(value.replace(/\s+/g, ""));
}

function placeholder(name: PublisherVariable) {
  return `[set ${name}]`;
}
